using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;
namespace QuietDread {
public partial class Game {
 class DeferredNarrator:INarrativeProvider {public TaskCompletionSource<string> completion=new TaskCompletionSource<string>();public Task<LocalModel[]> Models(CancellationToken ct){return Task.FromResult(new LocalModel[0]);}public Task<string> Generate(string model,string prompt,string tone,int tokens,CancellationToken ct){return completion.Task;}}
 class TimeoutNarrator:INarrativeProvider {public int calls;public Task<LocalModel[]> Models(CancellationToken ct){return Task.FromResult(new LocalModel[0]);}public async Task<string> Generate(string model,string prompt,string tone,int tokens,CancellationToken ct){calls++;await Task.Delay(Timeout.Infinite,ct);return "";}}
 Campaign NarrativeFixture(string mode){var c=Campaign.Create(data,mode,"vermin",data.F("vermin").defaults.ToList());c.ObserveChronicle();if(mode=="trail")c.Visit(c.nodes.First(c.Available));else c.Move(1);var b=c.MakeBattle();b.units.First(u=>u.team==0&&!b.P(u).commander).hp=0;var survivor=b.units.First(u=>u.team==0&&u.Alive&&!b.P(u).commander);survivor.hp=Math.Max(1,survivor.hp-9);survivor.kills=2;foreach(var foe in b.Living(1).Take(2).ToList())foe.hp=0;b.Add("clawrat",0,7,7,true).hp=0;b.finished=true;b.winner=0;b.score[0]=30;b.score[1]=12;c.Settle(b);foreach(var e in c.journal)e.generation="skipped";return c;}
 IEnumerator NarrativeSmoke(){Directory.CreateDirectory(qaDir);var report=new List<string>();var errors=new List<string>();Application.logMessageReceived+=(text,stack,type)=>{if(type==LogType.Error||type==LogType.Exception)errors.Add(text);};narrator.Changed=()=>{};narrator.settings=new NarratorSettings{enabled=true,model="fixture",endpoint="http://127.0.0.1:11434"};yield return null;
  var first=NarrativeFixture("trail");var entry=first.journal.Last(e=>e.kind=="battle");var delayed=new DeferredNarrator();narrator.ProviderOverride=delayed;narrator.Bind(first);narrator.Generate(entry);var replacement=NarrativeFixture("conquest");narrator.Bind(replacement);delayed.completion.SetResult(JsonUtility.ToJson(new StoryReply{eventId=entry.id,outcome=entry.outcome,commanderLost=entry.commanderLost,losses=entry.Lost(),survivors=entry.Survived(),thread="remember_fallen",text="Silence gathers around the relay while the weight of the recorded losses settles over the command post."}));yield return new WaitForSeconds(.2f);if(entry.source!="Authored fallback"||replacement.journal.Any(e=>e.source.StartsWith("Local AI")))errors.Add("Stale response mutated a switched campaign");else report.Add("PASS stale delayed response rejected after campaign switch");
  var stall=new TimeoutNarrator();narrator.ProviderOverride=stall;narrator.requestTimeoutSeconds=.08f;narrator.Generate(replacement.journal.Last(e=>e.kind=="battle"));float until=Time.realtimeSinceStartup+5;while(narrator.busy&&Time.realtimeSinceStartup<until)yield return null;if(narrator.busy||stall.calls!=2||replacement.journal.Last(e=>e.kind=="battle").generation!="fallback")errors.Add("Timeout retry/fallback failed");else report.Add("PASS timeout, one retry and authored fallback");narrator.Cancel();narrator.requestTimeoutSeconds=90;narrator.ProviderOverride=null;
  narrator.Discover();while(narrator.testing)yield return null;if(narrator.models.Length==0){errors.Add("No installed local model: "+narrator.status);}else{narrator.settings.model=narrator.models.FirstOrDefault(m=>m.name=="mistral-nemo-instruct:latest")?.name??narrator.models[0].name;report.Add("Local model: "+narrator.settings.model);
   foreach(var mode in new[]{"trail","conquest"}){campaign=NarrativeFixture(mode);narrator.Bind(campaign);entry=campaign.journal.Last(e=>e.kind=="battle");narrator.Generate(entry);until=Time.realtimeSinceStartup+190;while(narrator.busy&&Time.realtimeSinceStartup<until)yield return null;if(entry.generation!="complete"){errors.Add(mode+" real generation: "+narrator.status);File.WriteAllText(Path.Combine(qaDir,"narrative-"+mode+"-rejected.txt"),narrator.LastRawReply??"");}else report.Add("PASS real local "+mode+" narration: "+entry.text);screen="campaign";showJournal=true;journalIndex=campaign.journal.IndexOf(entry);journalCampaign=campaign.chronicleId;yield return new WaitForSeconds(.4f);ScreenCapture.CaptureScreenshot(Path.Combine(qaDir,"narrative-"+mode+".png"));File.WriteAllText(Path.Combine(qaDir,"narrative-"+mode+"-fixture.json"),JsonUtility.ToJson(campaign,true));yield return new WaitForSeconds(.5f);showJournal=false;}
  }
  narrator.settings.enabled=false;showNarrator=true;yield return new WaitForSeconds(.5f);ScreenCapture.CaptureScreenshot(Path.Combine(qaDir,"narrative-settings.png"));yield return new WaitForSeconds(.5f);File.WriteAllText(Path.Combine(qaDir,"narrative-runtime.txt"),(errors.Count==0?"PASS":"FAIL")+"\n"+string.Join("\n",report)+"\n"+string.Join("\n",errors));Application.Quit(errors.Count==0?0:1);
 }
}
}

